<?php foreach($contactGeography['municipalities'] as $municipality): $department=(string)$municipality['department_code']; $name=mb_convert_case($municipality['name'],MB_CASE_TITLE,'UTF-8'); $name=preg_replace_callback('/(?<=\.)([[:alpha:]])(?=\.)/u',static fn($match)=>mb_strtoupper($match[1],'UTF-8'),$name); ?><option data-landline-prefix="<?=$escape($contactGeography['prefixes'][$department]??'')?>" value="<?=$escape($municipality['code'])?>"><?=$escape($name.' · '.$contactGeography['departments'][$department])?></option><?php endforeach ?>
